Transformar números e objetos:

```
const precos = [10, 20, 30];

// Dobrar cada preço:
const dobrados = precos.map((p) => p * 2);
// devolve: [20, 40, 60]

// Transformar cada número em texto formatado:
const etiquetas = precos.map((p) => `R$ ${p},00`);
// devolve: ['R$ 10,00', 'R$ 20,00', 'R$ 30,00']

// Extrair uma propriedade de cada objeto:
const clientes = [{ nome: 'Ana' }, { nome: 'Beto' }];
const nomes = clientes.map((c) => c.nome);
// devolve: ['Ana', 'Beto']
```

Os três exemplos seguem o mesmo esqueleto: `lista.map((item) => transformacaoDoItem)`. A setinha diz COMO cada item vira.

code.code:
const precos = [10, 20, 30];

const dobrados = precos.map((p) => p * 2);
console.log(dobrados); // [20, 40, 60]

const etiquetas = precos.map((p) => `R$ ${p},00`);
console.log(etiquetas); // ['R$ 10,00', 'R$ 20,00', 'R$ 30,00']

console.log(precos); // [10, 20, 30] — a original não mudou
console.log(precos.length, dobrados.length); // 3 3 — mesmo tamanho

// Passo 1: conferimos que veio uma lista de verdade.
function obterNomes(clientes) {
  if (!Array.isArray(clientes)) {
    throw new Error('clientes precisa ser uma lista');
  }

  // Passo 2 e 3: cada cliente vira o nome dele, na mesma ordem.
  return clientes.map((cliente) => cliente.nome);
}

console.log(obterNomes([{ nome: 'Ana' }, { nome: 'Beto' }]));
// imprime: ['Ana', 'Beto']
